import designIndex from '../../../oracle/designs/index.json';

// Official example designs, generated by scripts/build-designs.sh. Each one is
// served as examples/<id>/leparagliding.txt plus its airfoils.
export interface Design {
  id: string;
  wing: string;
  program: string;
  cells: number;
  airfoils: string[];
  adapted: string;
}

export const DESIGNS: readonly Design[] = designIndex;
